import re
from dataclasses import dataclass

_NUMBER = r"(\d+(?:[.,]\d+)?)"
_PATTERNS = {
    "protein": re.compile(r"белки\s+" + _NUMBER),
    "fat": re.compile(r"жиры\s+" + _NUMBER),
    "carbs": re.compile(r"углеводы\s+" + _NUMBER),
    "kcal": re.compile(_NUMBER + r"\s*ккал"),
}
_LABELS = {"protein": "белки", "fat": "жиры", "carbs": "углеводы", "kcal": "ккал"}


@dataclass(frozen=True)
class Kbju:
    protein: float
    fat: float
    carbs: float
    kcal: float


def parse_kbju(value: str) -> Kbju:
    block = value.split("<br>", 1)[0]
    numbers = {}
    for field, pattern in _PATTERNS.items():
        match = pattern.search(block)
        if match is None:
            raise ValueError(f"в строке КБЖУ нет значения «{_LABELS[field]}»: {block!r}")
        numbers[field] = float(match.group(1).replace(",", "."))
    if numbers["kcal"] <= 0:
        raise ValueError(f"ккал в строке КБЖУ должны быть больше нуля: {block!r}")
    return Kbju(**numbers)

import html
from itertools import combinations

from core.kbju import parse_kbju
from core.scoring import score

KBJU_PROPERTY = "Пищевая и энергетическая ценность в 100 г"
MIN_WINNER_GAP = 0.03


def describe_product(item: dict) -> dict:
    """Товар ВкусВилла (из поиска или product_details) → id, название, КБЖУ, скор."""
    value = next((p["value"] for p in item.get("properties", []) if p["name"] == KBJU_PROPERTY), None)
    if value is None:
        raise ValueError(f"у товара {item['id']} нет КБЖУ: выбери другой товар")
    kbju = parse_kbju(value)
    return {
        "id": item["id"],
        "xml_id": item["xml_id"],
        "name": html.unescape(item["name"]),
        "kbju": {"protein": kbju.protein, "fat": kbju.fat, "carbs": kbju.carbs, "kcal": kbju.kcal},
        "score": score(kbju),
    }


def _single_winner(products: list[dict]) -> dict | None:
    first, second = sorted(products, key=lambda p: p["score"], reverse=True)[:2]
    # Скоры округлены до 3 знаков; без round 0.141 - 0.111 во float меньше 0.03.
    if round(first["score"] - second["score"], 3) < MIN_WINNER_GAP:
        return None
    return first


def check_query(query: str) -> None:
    """Проверка запроса до похода в поиск ВкусВилла."""
    if not query.strip():
        raise ValueError("поисковый запрос пуст: укажи категорию, например «творог»")


def build_round(query: str, items: list[dict]) -> dict:
    check_query(query)
    candidates = {}
    for item in items:
        if item["id"] in candidates:
            continue
        try:
            candidates[item["id"]] = describe_product(item)
        except ValueError:
            continue
    for triple in combinations(candidates.values(), 3):
        winner = _single_winner(list(triple))
        if winner is None:
            continue
        losers = [p for p in triple if p is not winner]
        # Позиция победителя зависит от id, а не от скора и порядка поиска.
        position = sum(p["id"] for p in triple) % 3
        products = losers[:position] + [winner] + losers[position:]
        return {"query": query, "products": products, "winner_id": winner["id"]}
    raise ValueError(
        f"по запросу «{query}» не нашлось трёх товаров с КБЖУ, где лучший опережает "
        f"второго на {MIN_WINNER_GAP} и больше: попробуй другой запрос или увеличь limit"
    )


def check_round(ids: list[int], choice_id: int) -> None:
    """Проверка id раунда и выбора до запросов за товарами."""
    if len(ids) != 3:
        raise ValueError(f"в раунде должно быть ровно 3 товара, передано {len(ids)}")
    if len(set(ids)) != 3:
        raise ValueError(f"товары в раунде повторяются: {ids}, нужны 3 разных id")
    if choice_id not in ids:
        raise ValueError(f"выбранный товар {choice_id} не из раунда: выбери один из {ids}")


def judge_round(products: list[dict], choice_id: int) -> dict:
    check_round([p["id"] for p in products], choice_id)
    described = [describe_product(p) for p in products]
    best = max(p["score"] for p in described)
    leaders = [p for p in described if p["score"] == best]
    if len(leaders) > 1:
        raise ValueError(f"у товаров {[p['id'] for p in leaders]} одинаковый лучший скор: победителя нет")
    winner_id = leaders[0]["id"]
    return {
        "correct": choice_id == winner_id,
        "winner_id": winner_id,
        "scores": {p["id"]: p["score"] for p in described},
    }

from mcp.server.fastmcp import FastMCP

from core.rounds import build_round as make_round
from core.rounds import check_query, check_round, describe_product
from core.rounds import judge_round as judge
from core.vkusvill import VkusVillClient

SEARCH_LIMIT = 10


def create_server(client: VkusVillClient) -> FastMCP:
    # INFO пишет в stderr строку на каждый запрос; в логах клиента это только шум.
    mcp = FastMCP("looksmax", log_level="WARNING")

    @mcp.tool()
    def score_product(product_id: int) -> dict:
        """Looksmax-скор товара ВкусВилла: id, название, КБЖУ на 100 г и белки × 4 / ккал."""
        return describe_product(_product_details(client, product_id))

    @mcp.tool()
    def build_round(query: str) -> dict:
        """Раунд из поиска ВкусВилла: 3 товара одной категории с КБЖУ и скором и winner_id."""
        check_query(query)
        return make_round(query, client.search(query, SEARCH_LIMIT))

    @mcp.tool()
    def judge_round(product_ids: list[int], choice_id: int) -> dict:
        """Судит выбор игрока: верно ли, winner_id и скоры трёх товаров по их product_details."""
        check_round(product_ids, choice_id)
        return judge([_product_details(client, product_id) for product_id in product_ids], choice_id)

    return mcp


def _product_details(client: VkusVillClient, product_id: int) -> dict:
    if product_id <= 0:
        raise ValueError(f"product_id должен быть больше нуля, передано {product_id}: возьми id товара из поиска")
    try:
        return client.product_details(product_id)
    except ValueError as e:
        raise ValueError(f"товар {product_id} не найден во ВкусВилле ({e}): проверь product_id") from e


if __name__ == "__main__":
    create_server(VkusVillClient()).run("stdio")

import copy
import json
import unittest
from itertools import combinations
from pathlib import Path

from core.rounds import build_round, judge_round

FIXTURES = Path(__file__).parent / "fixtures"
KBJU_PROPERTY = "Пищевая и энергетическая ценность в 100 г"


def items(fixture: str) -> list[dict]:
    return json.loads((FIXTURES / fixture).read_text(encoding="utf-8"))["data"]["items"]


def pick(fixture: str, *ids: int) -> list[dict]:
    by_id = {i["id"]: i for i in items(fixture)}
    return [by_id[i] for i in ids]


def details(fixture: str) -> dict:
    return json.loads((FIXTURES / fixture).read_text(encoding="utf-8"))["data"]


def without_kbju(item: dict) -> dict:
    item = copy.deepcopy(item)
    item["properties"] = [p for p in item["properties"] if p["name"] != KBJU_PROPERTY]
    return item


def with_kbju(item: dict, value: str) -> dict:
    item = copy.deepcopy(item)
    for p in item["properties"]:
        if p["name"] == KBJU_PROPERTY:
            p["value"] = value
    return item


def ids(round_: dict) -> set[int]:
    return {p["id"] for p in round_["products"]}


class BuildRoundTest(unittest.TestCase):
    def test_picks_three_products_with_single_winner(self):
        # чипсы: 65291 → 0.044, 81955 → 0.779, 26751 → 0.048 — первая тройка по порядку поиска
        round_ = build_round("чипсы", items("search_chips.json"))
        self.assertEqual(round_["query"], "чипсы")
        self.assertEqual(ids(round_), {65291, 81955, 26751})
        self.assertEqual(round_["winner_id"], 81955)

    def test_skips_triples_where_top_score_is_tied(self):
        # творог: 27695, 185, 21347 → 0.529; 24165, 188 → 0.408.
        # Две «пятипроцентные» пачки в одной тройке — ничья за первое место.
        round_ = build_round("творог", items("search_tvorog.json"))
        self.assertEqual(ids(round_), {27695, 24165, 188})
        self.assertEqual(round_["winner_id"], 27695)

    def test_products_carry_name_kbju_and_score(self):
        round_ = build_round("творог", items("search_tvorog.json"))
        product = next(p for p in round_["products"] if p["id"] == 27695)
        self.assertEqual(
            product,
            {
                "id": 27695,
                "xml_id": 27695,
                "name": "Творог 5%, 180 г",
                "kbju": {"protein": 16, "fat": 5, "carbs": 3, "kcal": 121},
                "score": 0.529,
            },
        )

    def test_ignores_items_without_valid_kbju(self):
        chips = items("search_chips.json")
        cases = {
            "нет свойства": without_kbju(chips[0]),
            "нет углеводов": with_kbju(chips[0], "белки 5,5 г, жиры 30 г; 504 ккал"),
        }
        for reason, broken in cases.items():
            with self.subTest(reason=reason):
                # без 65291 первая тройка — 81955, 26751, 110380
                round_ = build_round("чипсы", [broken] + chips[1:])
                self.assertEqual(ids(round_), {81955, 26751, 110380})

    def test_winner_beats_second_place_by_at_least_0_03(self):
        # 81955 0.779 с тремя чипсами около 0.04 — проходит; в остальных отрыв < 0.03
        tvorog = items("search_tvorog.json")
        with self.assertRaises(ValueError):
            # 0.529, 0.529, 0.529: победителя нет
            build_round("творог", tvorog[:3])
        with self.assertRaises(ValueError):
            # 0.044, 0.048, 0.047, 0.038: лучший опережает второго на 0.001
            build_round("чипсы", pick("search_chips.json", 65291, 26751, 110380, 74423))

    def test_gap_of_exactly_0_03_is_enough(self):
        a, b, c = pick("search_chips.json", 65291, 26751, 110380)
        given = [
            # во float 0.141 - 0.111 = 0.029999999999999985
            with_kbju(a, "белки 3.525 г, жиры 1 г, углеводы 1 г; 100 ккал"),  # 0.141
            with_kbju(b, "белки 2.775 г, жиры 1 г, углеводы 1 г; 100 ккал"),  # 0.111
            c,  # 0.047
        ]
        self.assertEqual(build_round("чипсы", given)["winner_id"], 65291)
        given[1] = with_kbju(b, "белки 2.8 г, жиры 1 г, углеводы 1 г; 100 ккал")  # 0.112
        with self.assertRaises(ValueError):
            build_round("чипсы", given)

    def test_fewer_than_three_products_with_kbju_raises_value_error(self):
        chips = items("search_chips.json")
        cases = {
            "два товара": chips[:2],
            "третий без КБЖУ": chips[:2] + [without_kbju(chips[2])],
            "третий — повтор первого": chips[:2] + [chips[0]],
            "пусто": [],
        }
        for reason, given in cases.items():
            with self.subTest(reason=reason):
                with self.assertRaises(ValueError):
                    build_round("чипсы", given)

    def test_empty_query_raises_value_error(self):
        for query in ("", "   "):
            with self.subTest(query=query):
                with self.assertRaises(ValueError):
                    build_round(query, items("search_chips.json"))

    def test_winner_position_varies_between_rounds(self):
        # 81955 с каждой парой из четырёх картофельных чипсов: шесть разных раундов
        others = [65291, 26751, 110380, 74423]
        positions = set()
        for a, b in combinations(others, 2):
            round_ = build_round("чипсы", pick("search_chips.json", 81955, a, b))
            positions.add([p["id"] for p in round_["products"]].index(81955))
        self.assertEqual(positions, {0, 1, 2})

    def test_same_input_gives_same_round(self):
        chips = items("search_chips.json")
        self.assertEqual(build_round("чипсы", chips), build_round("чипсы", chips))


class JudgeRoundTest(unittest.TestCase):
    def products(self) -> list[dict]:
        # 27695 из product_details (0.529), 24165 и 188 из поиска (0.408)
        return [details("details_27695.json")] + pick("search_tvorog.json", 24165, 188)

    def test_choosing_winner_is_correct(self):
        self.assertEqual(
            judge_round(self.products(), 27695),
            {"correct": True, "winner_id": 27695, "scores": {27695: 0.529, 24165: 0.408, 188: 0.408}},
        )

    def test_choosing_other_product_is_wrong(self):
        verdict = judge_round(self.products(), 188)
        self.assertFalse(verdict["correct"])
        self.assertEqual(verdict["winner_id"], 27695)

    def test_not_exactly_three_products_raises_value_error(self):
        tvorog = items("search_tvorog.json")
        for count in (2, 4):
            with self.subTest(count=count):
                with self.assertRaises(ValueError):
                    judge_round(tvorog[3:5] + tvorog[:count - 2], 24165)

    def test_repeated_product_raises_value_error(self):
        with self.assertRaises(ValueError):
            judge_round(pick("search_tvorog.json", 27695, 24165, 27695), 27695)

    def test_choice_outside_round_raises_value_error(self):
        with self.assertRaises(ValueError):
            judge_round(self.products(), 185)

    def test_product_without_kbju_raises_value_error(self):
        products = self.products()
        products[1] = without_kbju(products[1])
        with self.assertRaises(ValueError):
            judge_round(products, 27695)

    def test_tied_top_scores_raise_value_error(self):
        # 27695 и 185 — оба 0.529
        with self.assertRaises(ValueError):
            judge_round(pick("search_tvorog.json", 27695, 185, 24165), 27695)


if __name__ == "__main__":
    unittest.main()

import json
import urllib.request
from typing import Callable

MCP_URL = "https://mcp.vkusvill.ru/mcp"
# QRATOR перед mcp.vkusvill.ru отвечает 403 на User-Agent «Python-urllib/…».
_USER_AGENT = "looksmax-grocery/1.0"

Transport = Callable[[dict], dict]


def http_transport(payload: dict, url: str = MCP_URL) -> dict:
    request = urllib.request.Request(
        url,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Content-Type": "application/json",
            "Accept": "application/json, text/event-stream",
            "User-Agent": _USER_AGENT,
        },
    )
    with urllib.request.urlopen(request, timeout=20) as response:
        return json.loads(response.read().decode("utf-8"))


class VkusVillClient:
    def __init__(self, transport: Transport = http_transport):
        self._transport = transport

    def search(self, q: str, limit: int) -> list[dict]:
        data = self._call("vkusvill_products_search", {"q": q, "limit": limit, "mode": "full"})
        return data["items"]

    def product_details(self, product_id: int) -> dict:
        return self._call("vkusvill_product_details", {"id": product_id})

    def cart_link(self, xml_ids: list[int]) -> str:
        if not xml_ids:
            raise ValueError("корзина пуста: передай хотя бы один xml_id товара")
        products = [{"xml_id": xml_id, "q": 1} for xml_id in xml_ids]
        return self._call("vkusvill_cart_link_create", {"products": products})["link"]

    def _call(self, tool: str, arguments: dict):
        response = self._transport(
            {
                "jsonrpc": "2.0",
                "id": 1,
                "method": "tools/call",
                "params": {"name": tool, "arguments": arguments},
            }
        )
        if "error" in response:
            raise ValueError(f"ВкусВилл отклонил запрос {tool}: {response['error']['message']}")
        result = response["result"]
        text = "".join(part["text"] for part in result["content"] if part["type"] == "text")
        if result.get("isError"):
            raise ValueError(f"ВкусВилл вернул ошибку {tool}: {text}")
        body = json.loads(text)
        if not body["ok"]:
            raise ValueError(f"ВкусВилл вернул ошибку {tool}: {body['error']['message']}")
        return body["data"]

